#!/usr/bin/env python3
# Accueil : illustration tablette demandee par Louis
# Remplace les documents par la tablette dans la rubrique patrimoine.
from pathlib import Path
import hashlib, json, base64, zlib
ENTRIES = json.loads('[{"path": "index.html", "old_sha256": "96575ebb7847e444572f5aeb89fb91daafb5570b28b98ddfc103ef3cb2276d69", "new_sha256": "1bc8cb6e0cbfefd4c333e02745c641b465b3b64fd64a5e1fdbfacd4b8a329b80", "data": ""}]')
root = Path.cwd().resolve()
prepared = []
for entry in ENTRIES:
    path = (root / entry['path']).resolve()
    assert path.is_relative_to(root), entry['path']
    current = hashlib.sha256(path.read_bytes()).hexdigest() if path.exists() else None
    assert current == entry['old_sha256'], 'Concurrent change: ' + entry['path']
    data = zlib.decompress(base64.b64decode(entry['data'], validate=True))
    assert hashlib.sha256(data).hexdigest() == entry['new_sha256']
    prepared.append((path, data))
for path, data in prepared:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(data)
print('Homepage tablet illustration applied.')
